def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def pos(v, default=(0, 0)):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        return default

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def step_toward(src, dst):
        return [clamp_step(dst[0] - src[0]), clamp_step(dst[1] - src[1])]

    def step_away(src, dst):
        return [clamp_step(src[0] - dst[0]), clamp_step(src[1] - dst[1])]

    def nearest(points, origin):
        best = None
        best_d = None
        for p in points:
            if not isinstance(p, (list, tuple)) or len(p) < 2:
                continue
            pp = (p[0], p[1])
            d = manhattan(pp, origin)
            if best is None or d < best_d:
                best = pp
                best_d = d
        return best

    def farthest(points, origin):
        best = None
        best_d = None
        for p in points:
            if not isinstance(p, (list, tuple)) or len(p) < 2:
                continue
            pp = (p[0], p[1])
            d = manhattan(pp, origin)
            if best is None or d > best_d:
                best = pp
                best_d = d
        return best

    env = observation.get("environment_name", "resource_collection")
    sx, sy = pos(observation.get("self_position"), (0, 0))
    ox, oy = pos(observation.get("opponent_position"), (sx, sy))
    self_pos = (sx, sy)
    opp_pos = (ox, oy)

    grid_w = observation.get("grid_width", 0) or 0
    grid_h = observation.get("grid_height", 0) or 0
    center = (grid_w // 2, grid_h // 2) if grid_w and grid_h else self_pos

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward(self_pos, opp_pos)

        corners = [
            (0, 0),
            (0, max(0, grid_h - 1)),
            (max(0, grid_w - 1), 0),
            (max(0, grid_w - 1), max(0, grid_h - 1)),
        ]
        target = farthest(corners, opp_pos) or center
        move = step_toward(self_pos, target)
        if move == [0, 0]:
            move = step_away(self_pos, opp_pos)
        return move

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or []
        target = nearest(targets, self_pos)
        if target is None:
            opponent_cells = observation.get("opponent_cells") or observation.get("enemy_territory") or []
            target = nearest(opponent_cells, self_pos)
        if target is None:
            target = center if center != self_pos else opp_pos
        return step_toward(self_pos, target)

    resources = observation.get("resources") or observation.get("resource_positions") or []
    my_target = nearest(resources, self_pos)
    op_target = nearest(resources, opp_pos)

    if my_target is not None and op_target is not None:
        if manhattan(op_target, self_pos) + 1 < manhattan(my_target, self_pos):
            my_target = op_target

    if my_target is not None:
        return step_toward(self_pos, my_target)

    # No resources visible: pressure opponent or move to center to stay active.
    if manhattan(self_pos, opp_pos) <= 2:
        return step_away(self_pos, opp_pos)
    return step_toward(self_pos, center if center != self_pos else opp_pos)

